import{_ as t,o as a,c as o,a7 as s}from"./chunks/framework.C4ZIv4ii.js";const n="/falconcms/screenshots/slider-slide.webp",u=JSON.parse('{"title":"Slides & Backgrounds","description":"","frontmatter":{},"headers":[],"relativePath":"slider/slides.md","filePath":"slider/slides.md","lastUpdated":1788112837000}'),i={name:"slider/slides.md"};function r(d,e,l,c,h,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="slides-backgrounds" tabindex="-1">Slides &amp; Backgrounds <a class="header-anchor" href="#slides-backgrounds" aria-label="Permalink to &quot;Slides &amp; Backgrounds&quot;">​</a></h1><p>A slider is a stack of <strong>slides</strong>. Each slide has its own background, its own set of <a href="/falconcms/slider/layers.html">layers</a>, and its own entrance transition. This page covers building slides and everything about backgrounds.</p><p><img src="'+n+`" alt="The Slide tab in the slider editor"></p><p><em>The <strong>Slide</strong> tab holds everything that belongs to one slide — its name, an optional whole-slide link, its transition and speed, and the background colour and image.</em></p><hr><h2 id="managing-slides" tabindex="-1">Managing slides <a class="header-anchor" href="#managing-slides" aria-label="Permalink to &quot;Managing slides&quot;">​</a></h2><p>The <strong>Slides rail</strong> on the left of the editor lists every slide as a thumbnail.</p><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td><strong>Add a slide</strong></td><td>Click <strong>+</strong> at the bottom of the rail</td></tr><tr><td><strong>Select / edit</strong></td><td>Click a thumbnail — the canvas switches to that slide</td></tr><tr><td><strong>Reorder</strong></td><td>Drag a thumbnail up or down</td></tr><tr><td><strong>Rename</strong></td><td>Open the <strong>Slide</strong> tab → <em>Slide name</em></td></tr><tr><td><strong>Duplicate</strong></td><td><strong>Slide</strong> tab → <em>Duplicate slide</em></td></tr><tr><td><strong>Delete</strong></td><td>Hover a thumbnail and click the delete icon</td></tr></tbody></table><p>Open the <strong>Slide</strong> tab in the right panel to edit the currently selected slide.</p><hr><h2 id="backgrounds" tabindex="-1">Backgrounds <a class="header-anchor" href="#backgrounds" aria-label="Permalink to &quot;Backgrounds&quot;">​</a></h2><p>Every slide has a background, set in the <strong>Slide</strong> tab. Choose a background <strong>type</strong>:</p><h3 id="solid-colour" tabindex="-1">Solid colour <a class="header-anchor" href="#solid-colour" aria-label="Permalink to &quot;Solid colour&quot;">​</a></h3><p>A single flat colour behind the layers.</p><h3 id="gradient" tabindex="-1">Gradient <a class="header-anchor" href="#gradient" aria-label="Permalink to &quot;Gradient&quot;">​</a></h3><p>A linear gradient with a <strong>from</strong> colour, <strong>to</strong> colour and <strong>angle</strong> (degrees).</p><h3 id="image" tabindex="-1">Image <a class="header-anchor" href="#image" aria-label="Permalink to &quot;Image&quot;">​</a></h3><p>Pick from the <a href="/falconcms/guide/media.html">Media Library</a>. Control how it sits:</p><table tabindex="0"><thead><tr><th>Option</th><th>Values</th></tr></thead><tbody><tr><td><strong>Size</strong></td><td><code>cover</code>, <code>contain</code>, <code>auto</code>, or a custom <code>width% height%</code></td></tr><tr><td><strong>Position</strong></td><td><code>center</code>, the nine anchor points, or a custom <code>x% y%</code></td></tr><tr><td><strong>Repeat</strong></td><td><code>no-repeat</code>, <code>repeat</code>, <code>repeat-x</code>, <code>repeat-y</code></td></tr></tbody></table><p>The first slide&#39;s image is treated as the page&#39;s <strong>LCP</strong> element and preloaded automatically.</p><h3 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h3><p>Set a background <strong>video</strong> in three ways:</p><ul><li><strong>Self-hosted</strong> — a direct <code>.mp4</code> URL from the Media Library. Plays muted, looped and auto-playing; the image (if set) acts as its poster.</li><li><strong>YouTube</strong> — paste any YouTube URL; it&#39;s embedded, muted, looped and sized to <em>cover</em> the slide (no player chrome).</li><li><strong>Vimeo</strong> — paste any Vimeo URL; embedded in background mode.</li></ul><p>Video backgrounds are <strong>deferred</strong> — a slide only loads its video when it&#39;s about to be shown.</p><hr><h2 id="overlays" tabindex="-1">Overlays <a class="header-anchor" href="#overlays" aria-label="Permalink to &quot;Overlays&quot;">​</a></h2><p>An <strong>overlay</strong> sits on top of the image/video but <em>under</em> the layers — perfect for darkening a busy video so text stays readable.</p><ul><li><strong>Colour overlay</strong> — a single colour at an adjustable opacity</li><li><strong>Gradient overlay</strong> — a linear gradient (from · to · angle) at an adjustable opacity</li></ul><hr><h2 id="motion-effects" tabindex="-1">Motion effects <a class="header-anchor" href="#motion-effects" aria-label="Permalink to &quot;Motion effects&quot;">​</a></h2><h3 id="ken-burns" tabindex="-1">Ken Burns <a class="header-anchor" href="#ken-burns" aria-label="Permalink to &quot;Ken Burns&quot;">​</a></h3><p>A slow, cinematic zoom/pan on the background image while the slide is shown. Pick a direction (zoom in/out, pan) from the <strong>Slide</strong> tab. Previews live on the canvas.</p><h3 id="parallax" tabindex="-1">Parallax <a class="header-anchor" href="#parallax" aria-label="Permalink to &quot;Parallax&quot;">​</a></h3><p>When enabled (slider <strong>Settings</strong> tab), layers subtly shift as the visitor moves their mouse, giving the slide depth. Parallax respects the visitor&#39;s reduced-motion preference when that option is on.</p><hr><h2 id="slide-transitions" tabindex="-1">Slide transitions <a class="header-anchor" href="#slide-transitions" aria-label="Permalink to &quot;Slide transitions&quot;">​</a></h2><p>The <strong>transition</strong> controls how a slide animates <em>in</em> when the slider advances to it.</p><p>Set a <strong>global</strong> transition for the whole slider (Settings tab), and optionally <strong>override</strong> it per slide (Slide tab). Leave a slide&#39;s transition empty to use the global default.</p><p>Available transitions:</p><p><code>fade</code> · <code>slide-left</code> · <code>slide-right</code> · <code>slide-up</code> · <code>slide-down</code> · <code>zoom</code> · <code>zoom-out</code> · <code>fade-scale</code> · <code>rotate</code> · <code>rotate-ccw</code> · <code>roll</code> · <code>flip</code> (Y) · <code>flip-x</code> · <code>skew</code> · <code>glide-up</code> · <code>glide-down</code> · <code>blur</code></p><p>The transition <strong>speed</strong> (ms) is also global with an optional per-slide override. Every transition previews live on the canvas as you pick it.</p><hr><h2 id="whole-slide-link" tabindex="-1">Whole-slide link <a class="header-anchor" href="#whole-slide-link" aria-label="Permalink to &quot;Whole-slide link&quot;">​</a></h2><p>Make an <strong>entire slide clickable</strong> — set a <strong>Slide link</strong> in the Slide tab (with an optional <em>Open in a new tab</em>).</p><p>Falcon Slider is smart about precedence:</p><ul><li><strong>Interactive layers</strong> (buttons, layers with their own link, video, audio, HTML) keep their own click behaviour.</li><li><strong>Passive areas</strong> — empty space and plain text/image/shape/icon layers — follow the slide link.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────┐</span></span>
<span class="line"><span>│  Headline (passive) → slide link      │</span></span>
<span class="line"><span>│                                       │</span></span>
<span class="line"><span>│         [ Buy now ] → its own link    │</span></span>
<span class="line"><span>│                                       │</span></span>
<span class="line"><span>│  ← empty space anywhere → slide link  │</span></span>
<span class="line"><span>└──────────────────────────────────────┘</span></span></code></pre></div><p>This mirrors real anchor semantics, so middle-click, right-click → <em>Open in new tab</em>, and the <em>new tab</em> option all work as expected.</p><hr><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/falconcms/slider/layers.html">Layers</a> — add text, images, buttons and more on top of the background</li><li><a href="/falconcms/slider/animations.html">Animations</a> — animate each layer in</li></ul>`,51)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
